package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierEntry struct {
	TierLimit decimal.Decimal
	TierRate  decimal.Decimal
}

var tierEntries [4]TierEntry

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var salesRec SalesRec
var inputDone bool

func isInputDone() bool { return WsEofFlag == "Y" }
func setInputDone() { WsEofFlag = "Y" }

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func roundDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

func storeField(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate toward zero to scale, then keep low-order digits that fit
	d = d.Truncate(scale)
	// Overflow handling: keep low-order intDigits
	// Use modulus on scaled integer
	scaleMult := decimal.New(1, scale) // 10^scale
	scaled := d.Mul(scaleMult)         // integer value (may have .0)
	// scaled is integer decimal; separate integer part
	// For positive numbers, low-order digits = scaled mod 10^(intDigits+scale)
	// For negative, similar
	modBase := decimal.New(1, int32(intDigits+int(scale)))
	// Need to handle negative via truncation toward zero then mod
	neg := scaled.IsNegative()
	if neg {
		scaled = scaled.Neg()
	}
	// mod
	// scaled is integer, use Mod
	modVal := scaled.Mod(modBase)
	if neg {
		modVal = modVal.Neg()
	}
	result := modVal.Div(scaleMult)
	// Ensure scale
	result = result.Truncate(scale)
	return result
}

func formatNumericEdited(d decimal.Decimal, picture string) string {
	// picture contains Z,9,',','.'
	// Determine scale from picture: number of 9 after '.'
	scale := 0
	if idx := strings.Index(picture, "."); idx >= 0 {
		scale = len(picture) - idx - 1
	}
	// Round/truncate? MOVE formatting: value is already to correct scale, just format.
	// Ensure d has exactly scale decimals (truncate/pad)
	d = d.Truncate(int32(scale))

	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}

	// Build string with fixed decimals
	s := d.StringFixed(int32(scale)) // e.g. "1234.50" or "0.00" or "1234"
	// Split integer and fractional
	intPartStr := ""
	fracPartStr := ""
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", scale)
		}
		// pad frac
		if len(fracPartStr) < scale {
			fracPartStr = fracPartStr + strings.Repeat("0", scale-len(fracPartStr))
		}
	} else {
		intPartStr = s
	}

	// Picture integer part (before '.')
	picInt := picture
	if idx := strings.Index(picture, "."); idx >= 0 {
		picInt = picture[:idx]
	}
	// picInt includes commas
	// Count placeholder positions (Z and 9)
	placeholders := 0
	for _, c := range picInt {
		if c == 'Z' || c == '9' {
			placeholders++
		}
	}
	// Overflow: keep low-order digits
	if len(intPartStr) > placeholders {
		intPartStr = intPartStr[len(intPartStr)-placeholders:]
	}
	// Left pad intPartStr with zeros to placeholders length for mapping
	paddedInt := strings.Repeat("0", placeholders-len(intPartStr)) + intPartStr

	// Now map placeholders to picture left to right
	// Build integer formatted including commas
	// We need to know for each placeholder whether to suppress zero
	// Z suppression: leading zeros are spaces, continues until first non-zero digit or a '9' position
	// Commas inside suppressed zone become spaces.

	// Find index of last Z in placeholder sequence
	// Convert picInt to runes
	picRunes := []rune(picInt)
	// Build list of placeholder indices in picRunes order
	type ph struct {
		pos  int
		kind rune // Z or 9
		val  byte // digit char
	}
	var phs []ph
	pi := 0 // index into paddedInt
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			phs = append(phs, ph{pos: i, kind: ch, val: paddedInt[pi]})
			pi++
		}
	}
	// Determine suppression: find first index where digit != '0' (or we hit a 9 that forces display)
	// Z's before that are suppressed. Standard: suppress while digit is '0' and we haven't yet encountered non-zero.
	// But a '9' position always shows digit even if zero, and also stops suppression? Actually '9' always prints.
	// For pattern ZZZ,ZZ9 : the '9' at end ensures at least one digit prints.
	suppress := true
	for i, p := range phs {
		if p.val != '0' {
			suppress = false
			_ = i
			break
		}
		if p.kind == '9' {
			// this zero should be displayed, suppression ends
			suppress = false
			break
		}
		// if still suppress, continue; but need to know where suppression ends
	}
	// More precise: mark each placeholder as suppressed or not
	suppressed := make([]bool, len(phs))
	stillLeading := true
	for i, p := range phs {
		if stillLeading {
			if p.val != '0' {
				stillLeading = false
				suppressed[i] = false
			} else {
				if p.kind == '9' {
					stillLeading = false
					suppressed[i] = false
				} else {
					suppressed[i] = true
				}
			}
		} else {
			suppressed[i] = false
		}
	}

	// Build integer output
	outRunes := make([]rune, len(picRunes))
	for i, ch := range picRunes {
		outRunes[i] = ch
	}
	// Fill placeholders
	for i, p := range phs {
		if suppressed[i] {
			outRunes[p.pos] = ' '
		} else {
			outRunes[p.pos] = rune(p.val)
		}
	}
	// Commas in suppressed zone become spaces: a comma is suppressed if all placeholders to its left are suppressed and all placeholders to its right up to next comma? Simpler: if every placeholder to left is suppressed, comma becomes space. Actually COBOL: commas inside suppressed zone become spaces.
	// Implement: for each comma position, if all placeholder positions left of it are suppressed, then space.
	for i, ch := range picRunes {
		if ch == ',' {
			allLeftSuppressed := true
			anyLeftPh := false
			for j, p := range phs {
				if p.pos < i {
					anyLeftPh = true
					if !suppressed[j] {
						allLeftSuppressed = false
						break
					}
				}
			}
			// Also need to consider: if there is still leading suppression covering beyond comma?
			// Simpler: if all left placeholders suppressed, comma -> space
			if anyLeftPh && allLeftSuppressed {
				outRunes[i] = ' '
			} else {
				// also if no left placeholder (should not happen)
				// check if all placeholders left are suppressed
			}
			// For trailing suppression not relevant here
		}
	}
	intOut := string(outRunes)

	if scale > 0 {
		return intOut + "." + fracPartStr
	}
	return intOut
}

func formatRate(d decimal.Decimal) string {
	// PIC 9.99 -> integer 1 digit, scale 2, 9 always
	d = d.Truncate(2)
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	s := d.StringFixed(2) // "1.20" etc
	// Need to keep low-order integer digits: 1 digit
	parts := strings.SplitN(s, ".", 2)
	ip := parts[0]
	fp := parts[1]
	if len(ip) > 1 {
		ip = ip[len(ip)-1:]
	}
	if neg {
		// COBOL would show sign? Not needed
		return "-" + ip + "." + fp
	}
	return ip + "." + fp
}

func formatCount(v int64) string {
	// PIC 9(3) zero-padded to 3
	s := fmt.Sprintf("%03d", v)
	if len(s) > 3 {
		s = s[len(s)-3:]
	}
	return s
}

var salesFileScanner *bufio.Scanner
var salesFileLines []string
var salesFileIdx int

func MAINPARA() {
	INITPARA()
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		salesFileLines = []string{}
	} else {
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			line := sc.Text()
			salesFileLines = append(salesFileLines, line)
		}
		f.Close()
	}
	salesFileIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE already handled
	SUMMARYPARA()
}

func INITPARA() {
	tierEntries[0].TierLimit = decimal.NewFromFloat(1000.00)
	tierEntries[0].TierRate = decimal.NewFromFloat(2.50)
	// Use exact decimals to avoid float errors
	tierEntries[0].TierLimit = decimal.New(100000, -2)
	tierEntries[0].TierRate = decimal.New(250, -2)
	tierEntries[1].TierLimit = decimal.New(500000, -2)
	tierEntries[1].TierRate = decimal.New(400, -2)
	tierEntries[2].TierLimit = decimal.New(2000000, -2)
	tierEntries[2].TierRate = decimal.New(550, -2)
	tierEntries[3].TierLimit = decimal.New(99999999, -2)
	tierEntries[3].TierRate = decimal.New(725, -2)
}

func READPARA() {
	if salesFileIdx >= len(salesFileLines) {
		setInputDone()
		return
	}
	line := salesFileLines[salesFileIdx]
	salesFileIdx++
	// pad to 12 with spaces
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12]
	// numeric field: 8 digits implied 2 decimals
	trimmed := strings.TrimSpace(srSalesRaw)
	if trimmed == "" {
		trimmed = "0"
	}
	// digits only, may contain spaces? Remove spaces
	trimmed = strings.ReplaceAll(trimmed, " ", "0")
	// Actually if padded, spaces would be considered? But digits only.
	n, _ := decimal.NewFromString(trimmed)
	// Build with scale 2
	d := decimal.New(n.IntPart(), -2)
	salesRec.SrId = srId
	salesRec.SrSales = d
}

func PROCESSPARA() {
	WsTier = 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if salesRec.SrSales.Cmp(tierEntries[WsIdx-1].TierLimit) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE /100
	rate := tierEntries[WsTier-1].TierRate
	comp := salesRec.SrSales.Mul(rate).Shift(-2) // /100
	compRounded := roundDecimal(comp, 2)
	WsComm = storeField(compRounded, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = storeField(WsTotal, 9, 2)
	WsCount++

	WsSalesEd = formatNumericEdited(salesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatRate(rate)
	WsCommEd = formatNumericEdited(WsComm, "ZZZ,ZZ9.99")
	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	// WsTier is PIC 9 -> width 1 digit
	tierStr := fmt.Sprintf("%d", WsTier)
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatNumericEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsCount)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	MAINPARA()
}

